require_once __DIR__.'/includes/auth.php';require_permission('documents');$pdo=db();$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT d.*,r.full_name,r.barangay_id,r.address FROM document_requests d LEFT JOIN residents r ON r.id=d.resident_id WHERE d.id=?');$s->execute([$id]);$doc=$s->fetch();if(!$doc||$doc['status']!=='Issued'){http_response_code(404);exit('Issued document not found.');}$token=bin2hex(random_bytes(32));$pdo->prepare('INSERT INTO document_verifications (document_request_id,verification_token) VALUES (?,?) ON DUPLICATE KEY UPDATE verification_token=VALUES(verification_token),revoked_at=NULL')->execute([$id,$token]);audit_action('official_document_printed','document_requests',$id,$doc['document_type']);$verifyUrl='verify.php?document='.rawurlencode($doc['document_no']);$body='This certifies that the foregoing information is true and correct based on the barangay records available at the time of issuance.';if($doc['document_type']==='Certificate of residency')$body='This certifies that '.($doc['full_name']??$doc['requester_name']).' is a bona fide resident of this barangay at the address recorded in the registry.';if($doc['document_type']==='Certificate of indigency')$body='This certifies that the named resident is requesting certification for the stated purpose, subject to barangay verification.';
?><!doctype html><html><head><meta charset="utf-8"><title><?= h($doc['document_type']) ?></title><style>body{font-family:Georgia,serif;background:#f2f5f8;color:#19243b}.toolbar{max-width:780px;margin:20px auto;text-align:right}.toolbar button,.toolbar a{padding:10px 16px;background:#1769aa;color:#fff;border:0;border-radius:4px;text-decoration:none;font:13px Arial;cursor:pointer}.sheet{background:#fff;max-width:780px;min-height:950px;margin:0 auto;padding:65px 78px;box-shadow:0 4px 25px #17365d18;box-sizing:border-box}.head{text-align:center;border-bottom:3px double #1769aa;padding-bottom:20px}.head p{font:11px Arial;margin:4px}.head h1{font-size:25px;margin:12px 0 5px}.doc-title{text-align:center;margin:55px 0 38px;font-size:22px;text-transform:uppercase;letter-spacing:.12em}.body{font-size:16px;line-height:2.1;text-align:justify}.meta{font:12px Arial;margin-top:30px;border:1px solid #dce5ed;padding:12px;display:flex;justify-content:space-between}.sign{display:grid;grid-template-columns:1fr 1fr;gap:60px;text-align:center;margin-top:90px;font:12px Arial}.sign div{border-top:1px solid #333;padding-top:9px}.qr{font:10px Arial;margin-top:35px;text-align:center;color:#6e7d92}.qr img{width:86px;height:86px;margin:8px}@media print{body{background:#fff}.sheet{box-shadow:none;margin:0;max-width:none}.toolbar{display:none}}@media(max-width:700px){.sheet{padding:40px 25px}.sign{grid-template-columns:1fr;gap:55px}}</style></head><body><div class="toolbar"><button onclick="window.print()">Print official document</button> <a href="documents.php">Back</a></div><main class="sheet"><header class="head"><p>REPUBLIC OF THE PHILIPPINES</p><p>Province of ____________________ · Municipality of ____________________</p><h1>BARANGAY INFORMATION SYSTEM</h1><p>Official Barangay Certification</p></header><h2 class="doc-title"><?= h($doc['document_type']) ?></h2><div class="body"><p><?= h($body) ?></p><p>This certification is issued upon the request of <strong><?= h($doc['full_name']??$doc['requester_name']) ?></strong> for the purpose of <strong><?= h($doc['purpose']) ?></strong>.</p><p>Issued this <?= date('jS') ?> day of <?= date('F Y') ?> at the Barangay Office.</p></div><div class="meta"><span>Official no.: <strong><?= h($doc['document_no']) ?></strong></span><span>Request: <?= h($doc['request_no']) ?></span></div><div class="sign"><div>Prepared by<br><br>Staff in charge</div><div>Approved by<br><br><strong>HON. PUNONG BARANGAY</strong></div></div><div class="qr"><img src="https://quickchart.io/qr?text=<?= rawurlencode($verifyUrl) ?>&size=120" alt="Verification QR"><br>Scan or visit: <?= h($verifyUrl) ?></div></main></body></html>
